    return 0;
}

#include <stdio.h>

int main(void) {
    int x;
    while (scanf("%d", &x) != 1) {
        int ch;
        /* 一个一个取走字符，直到换行符或输入结束 */
        while ((ch = getchar()) != '\n' && ch != EOF) { }
        if (ch == EOF) return 1;          /* 已经没有输入了 */
        printf("不是整数，已丢弃这一行\n");
    }
    printf("读到 %d\n", x);
    return 0;
}

#include <stdio.h>

int main(void) {
    int ch;
    int count = 0;
    while ((ch = getchar()) != EOF) {
        count++;
    }
    printf("一共读到 %d 个字符\n", count);
    return 0;
}

