#include <stdio.h>

void swap_wrong(int a, int b) {   /* 形参是副本 */
    int t = a;
    a = b;
    b = t;
}

int main(void) {
    int x = 1, y = 2;
    swap_wrong(x, y);
    printf("x = %d, y = %d\n", x, y);
    return 0;
}

#include <stdio.h>

void swap(int *pa, int *pb) {     /* 形参是指针，接收地址 */
    int t = *pa;                  /* 顺着地址读写调用者的变量 */
    *pa = *pb;
    *pb = t;
}

int main(void) {
    int x = 1, y = 2;
    swap(&x, &y);                 /* 传的是地址 */
    printf("x = %d, y = %d\n", x, y);
    return 0;
}

#include <stdio.h>

/* 计算 a / b 的商和余数，通过指针带回 */
void divmod(int a, int b, int *q, int *r) {
    *q = a / b;
    *r = a % b;
}

int main(void) {
    int q = 0, r = 0;
    divmod(17, 5, &q, &r);
    printf("17 / 5 = %d 余 %d\n", q, r);
    return 0;
}

