}

int main(void) {
    report("cdecl", 3);
    report("stdcall", 3);
    return 0;
}

#include <stdio.h>

static int log[4];
static int steps;

static int note(int v) {
    log[steps++] = v;
    return v;
}

static int add3(int a, int b, int c) {
    return a + b + c;
}

int main(void) {
    int sum = add3(note(1), note(2), note(3));
    printf("sum = %d，实际求值顺序：", sum);
    for (int i = 0; i < steps; i++) {
        printf("%s%d", i ? " → " : "", log[i]);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>

typedef struct {
    int x;
    int y;
} Pair;

static Pair make(int x, int y) {
    Pair p = { x, y };
    return p;                    /* 返回的是 p 的副本 */
}

int main(void) {
    Pair a = make(1, 2);
    Pair b = a;                  /* 又一次复制 */
    b.x = 100;
    printf("a.x = %d, b.x = %d\n", a.x, b.x);
    return 0;
}

