#define CONFIG_LIMIT 999        /* 如果没有卫士，这行会把 50 悄悄改成 999 */
#endif

int main(void) {
    printf("CONFIG_LIMIT = %d\n", CONFIG_LIMIT);
    return 0;
}

#include <stdio.h>

/* ---------- 模拟头文件里的变量定义被包含两次 ---------- */
int g_limit = 100;

int g_limit = 100;               /* 错误：redefinition of 'g_limit' */

int main(void) {
    printf("%d\n", g_limit);
    return 0;
}

#include <stdio.h>

/* ---------- 模拟第一次包含 ---------- */
#ifndef STATS_H
#define STATS_H_
int twice(int x) { return 2 * x; }
#endif

/* ---------- 模拟第二次包含：卫士失效，又展开了一次 ---------- */
#ifndef STATS_H
#define STATS_H_
int twice(int x) { return 2 * x; }      /* redefinition of 'twice' */
#endif

int main(void) {
    printf("%d\n", twice(21));
    return 0;
}

