/* 按值传参：p 是 a 的一份独立副本，origin 只是用来对比地址 */
static void move_by_value(Point p, long long dx, long long dy, const Point *origin) {
    p.x += dx;
    p.y += dy;
    printf("函数内 p = (%lld, %lld)\n", p.x, p.y);
    printf("形参 p 和原变量是同一块内存吗？%s\n",
