/* 把 *buf 的容量扩到 need 个 int。成功返回 1；失败返回 0，此时 *buf 完全没被改动。 */
static int grow(int **buf, size_t *cap, size_t need) {
    if (need <= *cap) {
        return 1;
    }
    int *tmp = realloc(*buf, need * sizeof **buf);   /* 临时指针接住 */
    if (tmp == NULL) {
        return 0;                                    /* 旧指针、旧数据、旧容量都还在 */
    }
    *buf = tmp;                                      /* 只有成功才落到正式指针上 */
    *cap = need;
    return 1;
}

