/* 模拟"原地扩不下、只能搬家"：先分配新块，拷数据，再释放旧块 */
static int *grow_by_copy(int *old, size_t old_n, size_t new_n) {
    int *fresh = malloc(new_n * sizeof *fresh);
    if (fresh == NULL) {
        return NULL;                     /* 失败时旧块原封不动 */
    }
    for (size_t i = 0; i < old_n; i++) {
        fresh[i] = old[i];               /* 内容被复制过去，所以数据不会丢 */
