    printf("%d\n", APP_CAP);
    return 0;
}

#include <stdio.h>
#include "include/app.h"    /* 判题器把所有文件放在同一个目录，没有 include/ 这一层 */

int main(void) {
    printf("%d\n", APP_CAP);
    return 0;
}

#include <stdio.h>

int main(void) {
    printf("%zu\n", strlen("abc"));    /* 缺 #include <string.h> */
    return 0;
}

