#include <stdio.h>
#include <stdlib.h>

typedef struct DNode {
    int value;
    struct DNode *prev;
    struct DNode *next;
} DNode;

typedef struct {
    DNode *head;
    DNode *tail;
    int count;
} DList;

static void dlist_init(DList *L) {
    L->head = NULL;
    L->tail = NULL;
    L->count = 0;
}

static int dlist_append(DList *L, int value) {
    DNode *node = malloc(sizeof *node);
    if (node == NULL) {
        return 0;
    }
    node->value = value;
    node->prev = L->tail;
    node->next = NULL;
    if (L->tail != NULL) {
        L->tail->next = node;
    } else {
        L->head = node;                /* 空表：新节点同时是头 */
    }
    L->tail = node;
    L->count++;
    return 1;
}

static DNode *dlist_find(const DList *L, int value) {
    for (DNode *p = L->head; p != NULL; p = p->next) {
        if (p->value == value) {
            return p;
        }
    }
    return NULL;
}

/* 把 value 插到 pos 之后：四根指针，pos->next 最后改 */
static int dlist_insert_after(DList *L, DNode *pos, int value) {
    if (pos == NULL) {
        return 0;
    }
    DNode *node = malloc(sizeof *node);
    if (node == NULL) {
        return 0;
    }
    node->value = value;
    node->prev = pos;                  /* ① */
    node->next = pos->next;            /* ② 读的是旧后继 */
    if (pos->next != NULL) {
        pos->next->prev = node;        /* ③ 旧后继回头 */
    } else {
        L->tail = node;                /* pos 原来是尾巴 */
    }
    pos->next = node;                  /* ④ 最后才断开旧连接 */
    L->count++;
    return 1;
}

static int dlist_remove(DList *L, DNode *node) {
    if (node == NULL) {
        return 0;
    }
    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        L->head = node->next;
    }
    if (node->next != NULL) {
        node->next->prev = node->prev;
    } else {
        L->tail = node->prev;
    }
    free(node);
    L->count--;
    return 1;
}

/* 逐节点校验 p->prev->next == p，并确认节点个数与 count 一致 */
static int dlist_check(const DList *L) {
    const DNode *p = L->head;
    const DNode *back = NULL;
    int n = 0;
    while (p != NULL) {
        if (p->prev != back) {
            return 0;
        }
        back = p;
        p = p->next;
        n++;
    }
    return back == L->tail && n == L->count;
}

static void print_both(const char *label, const DList *L) {
    printf("%s正向：", label);
    for (const DNode *p = L->head; p != NULL; p = p->next) {
        if (p != L->head) {
            printf(" ");
        }
        printf("%d", p->value);
    }
    printf("\n%s反向：", label);
    for (const DNode *p = L->tail; p != NULL; p = p->prev) {
        if (p != L->tail) {
            printf(" ");
        }
        printf("%d", p->value);
    }
    printf("\n");
}

static int dlist_clear(DList *L) {
    int freed = 0;
    DNode *p = L->head;
    while (p != NULL) {
        DNode *next = p->next;
        free(p);
        p = next;
        freed++;
    }
    L->head = NULL;
    L->tail = NULL;
    L->count = 0;
    return freed;
}

int main(void) {
