#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

typedef struct {
    Node *head;      /* 队头：出队端 */
    Node *tail;      /* 队尾：入队端 */
    int size;
} Queue;

static int enqueue(Queue *q, int value) {
    Node *node = malloc(sizeof *node);
    if (node == NULL) {
        return 0;
    }
    node->value = value;
    node->next = NULL;
    if (q->tail == NULL) {           /* 空队列：head 和 tail 一起指向它 */
        q->head = node;
        q->tail = node;
    } else {                          /* 非空：接在尾节点后面，再更新 tail */
        q->tail->next = node;
        q->tail = node;
    }
    q->size++;
    return 1;
}

static int dequeue(Queue *q, int *out) {
    if (q->head == NULL) {
        return 0;
    }
    Node *node = q->head;
    q->head = node->next;
    if (q->head == NULL) {            /* 关键：摘掉的是最后一个节点 */
        q->tail = NULL;               /* 必须同时把 tail 清空 */
    }
    q->size--;
    *out = node->value;
    free(node);
    return 1;
}

static int peek(const Queue *q, int *out) {
    if (q->head == NULL) {
        return 0;
    }
    *out = q->head->value;
    return 1;
}

static void destroy(Queue *q) {
    int value = 0;
    while (dequeue(q, &value)) {
        /* 一直出队到空，节点就全部释放了 */
    }
}

