static void trace(const Node *root, int key) {
    int path[64];
    int steps = 0;
    int found = 0;

    while (root != NULL) {
        path[steps++] = root->key;
        if (root->key == key) {
            found = 1;
            break;
        }
        root = (key < root->key) ? root->left : root->right;
