            lo = mid;                      /* 错：应该是 mid + 1 */
            printf("（区间宽度变成 %d）\n", hi - lo);
        } else {
            hi = mid;
            printf("\n");
        }
    }
    printf("只要 lo 和 hi 相差 1，mid 就永远等于 lo，循环再也不会前进\n");
