    return x != 0u && (x & (x - 1u)) == 0u;   /* 去掉最低位的 1，看是否为 0 */
}

static int popcount(unsigned int x) {
    int c = 0;
    while (x != 0u) {
        x &= x - 1u;                          /* 每轮消掉最低位的 1 */
