#include <stdio.h>
#include <limits.h>

static int my_atoi(const char *s) {
    while (*s == ' ' || (*s >= '\t' && *s <= '\r')) {
        s++;                       /* 跳过所有空白字符 */
    }
    int sign = 1;
    if (*s == '+' || *s == '-') {
        if (*s == '-') {
            sign = -1;
        }
        s++;
    }
    long long v = 0;
    while (*s >= '0' && *s <= '9') {
        v = v * 10 + (*s - '0');
        if (sign > 0 && v > INT_MAX) {
            return INT_MAX;
        }
        if (sign < 0 && -v < INT_MIN) {
            return INT_MIN;
        }
        s++;
    }
    return (int)(sign > 0 ? v : -v);
}

int main(void) {
    const char *cases[6] = { "42", "  -17", "+0", "123abc", "999999999999", "-999999999999" };
    for (int i = 0; i < 6; i++) {
        printf("[%s] -> %d\n", cases[i], my_atoi(cases[i]));
    }
    return 0;
}

